  "inlineSchema": "// Tool Tracker — standalone schema (SQLite so it runs with no database server).\n//\n// MERGING INTO TRADIES DIARY: copy the four models below into the main\n// prisma/schema.prisma (MySQL). See MERGE_GUIDE.md for the two small extra lines\n// (Organisation relation) and the migrate command. Table names already use the\n// td_ prefix like the rest of Tradies Diary.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// One Walter gateway = one toolbox.\nmodel ToolTrackerDevice {\n  id             Int                 @id @default(autoincrement())\n  uuid           String              @unique @default(uuid())\n  organisationId Int                 @map(\"organisation_id\")\n  name           String\n  keyHash        String              @unique @map(\"key_hash\") // sha256 of the device key; the key itself is never stored\n  lastReportOn   DateTime?           @map(\"last_report_on\")\n  batteryV       Float?              @map(\"battery_v\")\n  latitude       Float?\n  longitude      Float?\n  gpsAccuracyM   Float?              @map(\"gps_accuracy_m\")\n  gpsOn          DateTime?           @map(\"gps_on\") // when the last good GPS fix was received\n  lteRsrp        Int?                @map(\"lte_rsrp\")\n  createdOn      DateTime            @default(now()) @map(\"created_on\")\n  updatedOn      DateTime            @updatedAt @map(\"updated_on\")\n  deleteFlag     Boolean             @default(false) @map(\"delete_flag\")\n  reports        ToolTrackerReport[]\n\n  @@index([organisationId])\n  @@map(\"td_tool_tracker_device\")\n}\n\n// One iBS05 tag stuck on one tool. Holds the tool's CURRENT state.\nmodel ToolTrackerTag {\n  id             Int                     @id @default(autoincrement())\n  uuid           String                  @unique @default(uuid())\n  organisationId Int                     @map(\"organisation_id\")\n  mac            String // aa:bb:cc:dd:ee:ff, lower case\n  name           String\n  notes          String?\n  toolInfoId     Int?                    @map(\"tool_info_id\") // optional link to Tradies Diary's existing tool list (td_tool_info)\n  inBox          Boolean                 @default(false) @map(\"in_box\")\n  lastSeenOn     DateTime?               @map(\"last_seen_on\") // heard at all (in or out of the box)\n  lastInBoxOn    DateTime?               @map(\"last_in_box_on\") // last report that had it IN the box\n  lastRssi       Int?                    @map(\"last_rssi\")\n  batteryV       Float?                  @map(\"battery_v\")\n  lastDeviceId   Int?                    @map(\"last_device_id\") // which toolbox it was last in\n  createdOn      DateTime                @default(now()) @map(\"created_on\")\n  updatedOn      DateTime                @updatedAt @map(\"updated_on\")\n  deleteFlag     Boolean                 @default(false) @map(\"delete_flag\")\n  items          ToolTrackerReportItem[]\n\n  @@unique([organisationId, mac])\n  @@map(\"td_tool_tracker_tag\")\n}\n\n// One message from Walter (e.g. once a day, or when the lid closes).\nmodel ToolTrackerReport {\n  id             Int                     @id @default(autoincrement())\n  uuid           String                  @unique @default(uuid())\n  organisationId Int                     @map(\"organisation_id\")\n  deviceId       Int                     @map(\"device_id\")\n  device         ToolTrackerDevice       @relation(fields: [deviceId], references: [id])\n  receivedOn     DateTime                @default(now()) @map(\"received_on\")\n  batteryV       Float?                  @map(\"battery_v\")\n  latitude       Float?\n  longitude      Float?\n  gpsAccuracyM   Float?                  @map(\"gps_accuracy_m\")\n  lteRsrp        Int?                    @map(\"lte_rsrp\")\n  lidClosed      Boolean?                @map(\"lid_closed\")\n  firmware       String?\n  items          ToolTrackerReportItem[]\n\n  @@index([deviceId, receivedOn])\n  @@index([organisationId, receivedOn])\n  @@map(\"td_tool_tracker_report\")\n}\n\n// One line per tag in a report. change = \"RETURNED\" / \"LEFT\" when the tool's state flipped.\nmodel ToolTrackerReportItem {\n  id        Int               @id @default(autoincrement())\n  reportId  Int               @map(\"report_id\")\n  report    ToolTrackerReport @relation(fields: [reportId], references: [id], onDelete: Cascade)\n  tagId     Int?              @map(\"tag_id\") // null = unknown tag (not in the tool list yet)\n  tag       ToolTrackerTag?   @relation(fields: [tagId], references: [id])\n  mac       String\n  inBox     Boolean           @map(\"in_box\")\n  heard     Boolean           @default(true)\n  rssi      Int?\n  strongPct Int?              @map(\"strong_pct\")\n  batteryV  Float?            @map(\"battery_v\")\n  change    String? // RETURNED | LEFT | null\n\n  @@index([reportId])\n  @@index([tagId])\n  @@index([mac])\n  @@map(\"td_tool_tracker_report_item\")\n}\n",
